mapper.select:
UPDATE ${admin.users} SET failed_login_count = failed_login_count + 1, updated_at = #{now}
WHERE id = #{id}
RETURNING failed_login_count

mapper.update:
UPDATE ${admin.users}
SET failed_login_count = 0, locked_until = NULL, last_login_at = #{now}, updated_at = #{now}
WHERE id = #{id}

UPDATE ${admin.users}
SET password_hash = #{passwordHash}, password_changed_at = #{now}, failed_login_count = 0, locked_until = NULL,
    updated_at = #{now}, version = version + 1
WHERE id = #{id}

UPDATE ${admin.users}
SET totp_secret_enc = #{secretEnc}, totp_enabled_at = NULL, totp_last_used_step = NULL,
    totp_disabled_at = NULL, updated_at = #{now}
WHERE id = #{id} AND totp_enabled_at IS NULL

UPDATE ${admin.users}
SET totp_enabled_at = #{now}, totp_last_used_step = #{usedStep}, totp_disabled_at = NULL, updated_at = #{now}
WHERE id = #{id} AND totp_secret_enc IS NOT NULL

UPDATE ${admin.users}
SET totp_secret_enc = NULL, totp_enabled_at = NULL, totp_last_used_step = NULL, totp_disabled_at = NULL,
    updated_at = #{now}
WHERE id = #{id}

UPDATE ${admin.users}
SET display_name = COALESCE(#{displayName}, display_name),
    preferred_language = COALESCE(#{language}, preferred_language), updated_at = #{now}
WHERE id = #{id}

mapper.select:
UPDATE ${admin.resetTokens} SET used_at = #{now}
WHERE token_hash = #{tokenHash} AND used_at IS NULL AND expires_at > #{now}
RETURNING ${admin.userId}
